CREATE TABLE members(id VARCHAR(36) PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password VARCHAR(100) NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('ADMIN','EDITOR','VIEWER')));
CREATE TABLE posts(id VARCHAR(36) PRIMARY KEY,title VARCHAR(140) NOT NULL,body VARCHAR(2200) NOT NULL,channel VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','SCHEDULED','QUEUED','PUBLISHED')),scheduled_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published_at TIMESTAMP WITH TIME ZONE,author_id VARCHAR(36) REFERENCES members(id),impressions BIGINT NOT NULL DEFAULT 0,engagements BIGINT NOT NULL DEFAULT 0);
CREATE INDEX posts_schedule ON posts(status,scheduled_at);
CREATE TABLE comments(id VARCHAR(36) PRIMARY KEY,post_id VARCHAR(36) REFERENCES posts(id) ON DELETE CASCADE,author_id VARCHAR(36) REFERENCES members(id),body VARCHAR(1000) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE notifications(id VARCHAR(36) PRIMARY KEY,message VARCHAR(250) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE notification_reads(notification_id VARCHAR(36) REFERENCES notifications(id) ON DELETE CASCADE,member_id VARCHAR(36) REFERENCES members(id),PRIMARY KEY(notification_id,member_id));
